from collections import deque
def comps(g,val):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==val and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); c=[]
                while q:
                    a,b=q.popleft(); c.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and g[na][nb]==val and (na,nb) not in seen:
                            seen.add((na,nb)); q.append((na,nb))
                out.append(c)
    return out
